}

{
  "key_claims": [
    {
      "claim_id": "c1",
      "text": "Rãnh khuyết hình chữ V ở sát viền nướu gây buốt khi gặp lạnh là tổn thương mòn ngót cổ răng (khuyết hình chêm) [P1], do sự kết hợp giữa ứng suất lực nhai uốn cong thân răng và cọ xát cơ học từ thói quen chải răng ngang [I1].",
      "citations": [
        "I1",
        "P1"
      ]
    },
    {
      "claim_id": "c2",
      "text": "Giải pháp phục hồi tối ưu theo phác đồ kỹ thuật Bộ Y Tế là trám bít che kín các ống ngà lộ bằng vật liệu Composite thẩm mỹ có độ đàn hồi cao [P1], giúp dứt điểm triệu chứng ê buốt và bảo vệ tủy răng [I1].",
      "citations": [
        "I1",
        "P1"
      ]
